 public static HabitatState State;public static List<int[]> Route=new List<int[]>();static Tuning tune=new Tuning{animalMovement=false};static int[] dx={0,1,0,-1},dz={1,0,-1,0};
 static object Copy(object src,Type t){if(src==null)return null;if(t.IsEnum)return Enum.ToObject(t,(int)src);if(t.IsPrimitive||t==typeof(string))return src;if(t.IsArray){var a=(Array)src;var b=Array.CreateInstance(t.GetElementType(),a.Length);for(int i=0;i<a.Length;i++)b.SetValue(Copy(a.GetValue(i),t.GetElementType()),i);return b;}if(typeof(IList).IsAssignableFrom(t)){var b=(IList)Activator.CreateInstance(t);foreach(var a in (IEnumerable)src)b.Add(Copy(a,t.GetGenericArguments()[0]));return b;}var result=Activator.CreateInstance(t);foreach(var f in t.GetFields()){var sf=src.GetType().GetField(f.Name);if(sf!=null)f.SetValue(result,Copy(sf.GetValue(src),f.FieldType));}return result;}
 sealed class N{public HabitatState s;public List<int[]> r;public int depth;}
 static Dictionary<int,List<int[]>> Walk(HabitatState s){var p=new Dictionary<int,List<int[]>>();var q=new Queue<int>();int start=s.playerZ*s.width+s.playerX;p[start]=new List<int[]>();q.Enqueue(start);while(q.Count>0){int id=q.Dequeue();for(int d=0;d<4;d++){var c=HabitatRules.Clone(s);c.playerX=id%s.width;c.playerZ=id/s.width;if(!HabitatRules.MovePlayer(c,dx[d],dz[d],true,tune))continue;int n=c.playerZ*s.width+c.playerX;if(p.ContainsKey(n))continue;var path=new List<int[]>(p[id]);path.Add(new[]{0,dx[d],dz[d]});p[n]=path;q.Enqueue(n);}}return p;}
 static string Key(HabitatState s,int region){var b=new System.Text.StringBuilder(region+":"+s.magnets+":");for(int i=0;i<s.tiles.Length;i++)if(HabitatRules.IsBox(s.tiles[i].prop))b.Append(i+","+(int)s.tiles[i].prop+","+(int)s.tiles[i].coveredProp+";");return b.ToString();}
 static bool Match(HabitatState a,HabitatState b)=>a.tiles.Select((t,i)=>t.prop==b.tiles[i].prop&&t.coveredProp==b.tiles[i].coveredProp).All(x=>x);
 static int Score(HabitatState s,HabitatState goal,int depth){int score=depth+(1-s.magnets)*200;for(int i=0;i<s.tiles.Length;i++){if(s.tiles[i].prop!=goal.tiles[i].prop||s.tiles[i].coveredProp!=goal.tiles[i].coveredProp)score+=25;if(HabitatRules.IsBox(goal.tiles[i].prop)){int best=99;for(int j=0;j<s.tiles.Length;j++)if(HabitatRules.IsBox(s.tiles[j].prop))best=Math.Min(best,Math.Abs(i%s.width-j%s.width)+Math.Abs(i/s.width-j/s.width));score+=best*10;}}return score;}
 static void Go(int x,int z){var walk=Walk(State);foreach(var a in walk[z*State.width+x])Act(a);}
 static void Arrange(HabitatState goal,int step){if(State.levelIndex==10&&step==125){Go(11,6);Act(new[]{7,6,10,7,0,-1});Act(new[]{11,10,6});Go(10,6);Act(new[]{11,9,6});Go(8,5);Act(new[]{11,8,6});Go(8,6);Act(new[]{7,6,8,7,-1,0});return;}if(State.levelIndex==10&&step==47){Go(11,10);Act(new[]{12,0,1});Act(new[]{12,0,1});Act(new[]{11,11,11});Go(12,10);Act(new[]{11,11,10});Go(11,10);Act(new[]{11,10,10});Go(9,11);Act(new[]{12,0,1});Go(10,11);Act(new[]{11,9,11});Go(9,11);Act(new[]{11,8,11});Go(goal.playerX,goal.playerZ);if(!Match(State,goal))throw new Exception("second manual transport mismatch");return;}if(State.levelIndex==10&&step==34){Go(10,12);Act(new[]{14,0,-1});Act(new[]{7,5,10,11,0,-1});Go(11,12);Act(new[]{11,11,11});Go(12,10);Act(new[]{11,11,10});Go(11,10);Act(new[]{11,10,10});Go(9,11);Act(new[]{12,0,1});Go(10,11);Act(new[]{11,9,11});Go(goal.playerX,goal.playerZ);if(!Match(State,goal))throw new Exception("manual transport mismatch");return;}var open=new SortedDictionary<int,Queue<N>>();var seen=new HashSet<string>();Action<N,int> add=(n,k)=>{if(!open.TryGetValue(k,out var q)){q=new Queue<N>();open[k]=q;}q.Enqueue(n);};add(new N{s=HabitatRules.Clone(State),r=new List<int[]>()},0);int count=0;while(open.Count>0&&count<30000){int k=open.First().Key;var n=open[k].Dequeue();if(open[k].Count==0)open.Remove(k);var walk=Walk(n.s);if(!seen.Add(Key(n.s,walk.Keys.Min())))continue;count++;int end=goal.playerZ*goal.width+goal.playerX;if(Match(n.s,goal)&&walk.ContainsKey(end)){n.r.AddRange(walk[end]);foreach(var a in n.r)Act(a);return;}
 foreach(var p in walk){int x=p.Key%n.s.width,z=p.Key/n.s.width;for(int d=0;d<4;d++){int bx=x+dx[d],bz=z+dz[d];var t=HabitatRules.TileAt(n.s,bx,bz);if(t==null||!HabitatRules.IsBox(t.prop))continue;for(int act=0;act<7;act++){var s=HabitatRules.Clone(n.s);s.playerX=x;s.playerZ=z;s.events.Clear();bool ok=act==0?HabitatRules.PushBox(s,bx,bz):act==1?HabitatRules.PullPlayer(s,-dx[d],-dz[d]):act==2?HabitatRules.RecoverBox(s,bx,bz):HabitatRules.UseUtility(s,6,bx,bz,dx[act-3],dz[act-3]);if(!ok)continue;var r=new List<int[]>(n.r);r.AddRange(p.Value);r.Add(act==0?new[]{11,bx,bz}:act==1?new[]{12,-dx[d],-dz[d]}:act==2?new[]{13,bx,bz}:new[]{7,6,bx,bz,dx[act-3],dz[act-3]});add(new N{s=s,r=r,depth=n.depth+1},Score(s,goal,n.depth+1));}}}
 if(n.s.magnets>0)foreach(var p in walk)for(int ox=-1;ox<=1;ox+=2)for(int oz=-1;oz<=1;oz+=2){int x=p.Key%n.s.width,z=p.Key/n.s.width,bx=x+ox,bz=z+oz;var t=HabitatRules.TileAt(n.s,bx,bz);if(t==null||!HabitatRules.IsBox(t.prop))continue;for(int d=0;d<4;d++){var s=HabitatRules.Clone(n.s);s.playerX=x;s.playerZ=z;s.events.Clear();if(!HabitatRules.UseUtility(s,6,bx,bz,dx[d],dz[d]))continue;var r=new List<int[]>(n.r);r.AddRange(p.Value);r.Add(new[]{7,6,bx,bz,dx[d],dz[d]});add(new N{s=s,r=r,depth=n.depth+1},Score(s,goal,n.depth+1));}}
 }
 throw new Exception("No replacement of legacy box transfer ending step "+step+" within "+count+" macro states; not proof of map unsolvability");}
 static void Act(int[] a){bool ok=true;switch(a[0]){case 10:HabitatRules.MovePlayer(State,a[1],a[2],true,tune);break;case 0:ok=HabitatRules.MovePlayer(State,a[1],a[2],true,tune);break;case 1:ok=HabitatRules.Interact(State,a[1],a[2]);break;case 2:ok=HabitatRules.Lure(State,a[1],a[2]);break;case 3:ok=HabitatRules.Rotate(State,a[1],a[2]);break;case 4:ok=HabitatRules.StoreHeld(State);break;case 5:ok=HabitatRules.TakeBagProp(State,a[1]);break;case 6:HabitatRules.Tick(State,tune,a[1]/10f);break;case 7:ok=HabitatRules.UseUtility(State,a[1],a[2],a[3],a[4],a[5]);break;case 8:ok=HabitatRules.Shop(State,a[1]==7?"launcher":a[1]==6?"magnet":a[1]==5?"shovel":"crate");break;case 14:State.facingX=a[1];State.facingZ=a[2];break;case 9:ok=HabitatRules.TransferBoatCrate(State,true);break;case 11:ok=HabitatRules.PushBox(State,a[1],a[2]);break;case 12:ok=HabitatRules.PullPlayer(State,a[1],a[2]);break;case 13:ok=HabitatRules.RecoverBox(State,a[1],a[2]);break;}if(!ok)throw new Exception("new step ["+string.Join(",",a)+"] "+State.message);Route.Add(a);}
 static void Old(LegacyHabitatIsland.HabitatState s,int[] a){var t=new LegacyHabitatIsland.Tuning{animalMovement=false};bool ok=true;switch(a[0]){case 10:LegacyHabitatIsland.HabitatRules.MovePlayer(s,a[1],a[2],true,t);break;case 0:ok=LegacyHabitatIsland.HabitatRules.MovePlayer(s,a[1],a[2],true,t);break;case 1:ok=LegacyHabitatIsland.HabitatRules.Interact(s,a[1],a[2]);break;case 2:ok=LegacyHabitatIsland.HabitatRules.Lure(s,a[1],a[2]);break;case 3:ok=LegacyHabitatIsland.HabitatRules.Rotate(s,a[1],a[2]);break;case 4:ok=LegacyHabitatIsland.HabitatRules.StoreHeld(s);break;case 5:ok=LegacyHabitatIsland.HabitatRules.TakeBagProp(s,a[1]);break;case 6:LegacyHabitatIsland.HabitatRules.Tick(s,t,a[1]/10f);break;case 7:ok=LegacyHabitatIsland.HabitatRules.UseUtility(s,a[1],a[2],a[3],a[4],a[5]);break;case 8:ok=LegacyHabitatIsland.HabitatRules.Shop(s,a[1]==7?"launcher":a[1]==6?"magnet":"crate");break;case 9:ok=LegacyHabitatIsland.HabitatRules.TransferBoatCrate(s,true);break;}if(!ok)throw new Exception("legacy route failed "+s.message);}
 public static string Run(int level,int[][] route){Route.Clear();var old=LegacyHabitatIsland.HabitatLevels.Create(level);old.rod=old.specialRod=old.backBasketUnlocked=true;old.coins=2000;old.chapterOneAccepted=old.chapterOneDelivered=old.chapterOneMorningSeen=true;old.campaignUnlockedStage=5;if(level==6)old.bagProps.Add(LegacyHabitatIsland.PropKind.Fan);State=(HabitatState)Copy(old,typeof(HabitatState));if(level==10){Act(new[]{8,5,0});for(int j=0;j<2;j++)Act(new[]{8,6,0});}
 for(int i=0;i<route.Length;i++){var a=route[i];if(a[0]==4)continue;if(level==10&&a[0]==8&&a[1]==7){Old(old,a);continue;}if(level==10&&i==126){Old(old,a);continue;}bool recover=a[0]==1&&old.carryingProp==LegacyHabitatIsland.PropKind.None&&LegacyHabitatIsland.HabitatRules.IsRecoveryTarget(old,a[1],a[2]);try{Old(old,a);}catch(Exception e){throw new Exception("legacy at "+i+" ["+string.Join(",",a)+"] "+e.Message);}if(HabitatRules.IsBox((PropKind)old.carryingProp)){if(a[0]==9){bool unloaded=false;foreach(var p in Walk(State)){var s=HabitatRules.Clone(State);s.playerX=p.Key%s.width;s.playerZ=p.Key/s.width;if(!HabitatRules.AtDock(s))continue;for(int d=0;d<4;d++){var c=HabitatRules.Clone(s);c.facingX=dx[d];c.facingZ=dz[d];if(!HabitatRules.TransferBoatCrate(c,true))continue;foreach(var m in p.Value)Act(m);State.facingX=dx[d];State.facingZ=dz[d];Route.Add(new[]{14,dx[d],dz[d]});Act(new[]{9,1,0});unloaded=true;break;}if(unloaded)break;}if(!unloaded)throw new Exception("no unloading spot");}
 while(i+1<route.Length&&HabitatRules.IsBox((PropKind)old.carryingProp))Old(old,route[++i]);var goal=(HabitatState)Copy(old,typeof(HabitatState));File.WriteAllText("Verification/feedback-20261018-140142/adapter-progress.txt","level="+level+" replace transfer ending="+i);File.WriteAllLines("Verification/feedback-20261018-140142/adapter-goal.txt",State.tiles.Select((t,k)=>k%State.width+","+k/State.width+" h="+t.height+" "+t.prop+" -> "+goal.tiles[k].prop).Where((t,k)=>State.tiles[k].prop!=goal.tiles[k].prop).Concat(new[]{"P "+State.playerX+","+State.playerZ+" -> "+goal.playerX+","+goal.playerZ}));Arrange(goal,i);
 }else Act(recover?new[]{13,a[1],a[2]}:a);}
 return (HabitatMechanicLevels.CompleteHabitat(State,tune)?"PASS":"FAIL")+" level="+level+" push-only actions="+Route.Count;
